use std::time::Instant;
use sha2::{Digest,Sha256};
use volna_trace::{session::{LocalSession,Session},remote::{hierarchy::Header,objects::TrackPayload}};
fn main() {
    let args:Vec<_>=std::env::args().collect();
    let start=Instant::now();
    let session=LocalSession::open(std::path::Path::new(&args[1])).unwrap();
    let open=start.elapsed().as_secs_f64();
    let track=session.tracks().iter().find(|t|t.path.join(".").contains("warp_slot[0].Instruction")).unwrap().id;
    let start=Instant::now();
    let loaded=session.load_track(track).unwrap();
    let load=start.elapsed().as_secs_f64();
    let bytes=loaded.generators.iter().map(|g|g.resident_bytes()).sum::<u64>();
    let rows=loaded.generators.iter().map(|g|g.transactions().len()).sum::<usize>();
    let checksum=loaded.generators.iter().flat_map(|g|g.transactions()).fold(0u64,|s,t|s.wrapping_add(t.id.0).wrapping_add(t.begin).wrapping_add(t.end));
    let header=bincode::serialize(&Header::borrowed(&session,"benchmark".into()).unwrap()).unwrap();
    let payload=bincode::serialize(&TrackPayload::from_loaded(&loaded)).unwrap();
    let header_sha=format!("{:x}",Sha256::digest(&header));
    let track_sha=format!("{:x}",Sha256::digest(&payload));
    let start=Instant::now();drop(loaded);let release_track=start.elapsed().as_secs_f64();
    let start=Instant::now();drop(session);let close=start.elapsed().as_secs_f64();
    println!("{{\"open\":{open},\"load\":{load},\"release_track\":{release_track},\"close\":{close},\"bytes\":{bytes},\"rows\":{rows},\"checksum\":{checksum},\"header_bytes\":{},\"track_bytes\":{},\"header_sha\":\"{header_sha}\",\"track_sha\":\"{track_sha}\"}}",header.len(),payload.len());
}

