use std::{io::Write, path::Path};
use volna_trace::session::LocalSession;
use vtr::{Attribute, SourceOptions, Value, Writer};
fn main() {
    let levels:usize=std::env::args().nth(1).unwrap().parse().unwrap();
    let path=Path::new(env!("CARGO_MANIFEST_DIR")).join(format!("drop-{levels}.vtr"));
    let mut writer=Writer::create(&path).unwrap();
    let key=writer.intern("description").unwrap();
    let mut value=writer.intern_value(Value::U64(1)).unwrap();
    for _ in 0..levels { value=writer.intern_value(Value::List(vec![Value::Ref(value)])).unwrap(); }
    let mut source=SourceOptions::new("instructions",None);
    source.attributes=vec![Attribute { key, value:Value::Ref(value) }];
    writer.transactions::<()>(source,"INSTRUCTION").unwrap();writer.close().unwrap();
    println!("written {} levels, {} bytes",levels,std::fs::metadata(&path).unwrap().len());
    let session=LocalSession::open(&path).unwrap();
    println!("opened");std::io::stdout().flush().unwrap();
    drop(session);
    println!("closed");
}

